import 'express-async-errors';
import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import cookieParser from 'cookie-parser';
import path from 'path';
import { env } from './config/env';
import { prisma } from './config/database';
import { errorHandler } from './middleware/errorHandler';
import { authRouter } from './routes/auth.routes';
import { usersRouter } from './routes/users.routes';
import { tripsRouter } from './routes/trips.routes';
import { requestsRouter } from './routes/requests.routes';
import { paymentsRouter } from './routes/payments.routes';
import { ratingsRouter } from './routes/ratings.routes';
import { reportsRouter } from './routes/reports.routes';
import { adminRouter } from './routes/admin.routes';

export function createApp() {
  const app = express();

  // ─── Seguridad y parsers ──────────────────────────────────────────────────
  app.use(helmet());
  app.use(
    cors({
      origin: env.FRONTEND_URL,
      credentials: true,
    }),
  );
  app.use(express.json());
  app.use(express.urlencoded({ extended: true }));
  app.use(cookieParser());

  // ─── Ruta raíz ───────────────────────────────────────────────────────────
  app.get('/', (_req, res) => {
    res.json({ message: 'API UTAxi - Servidor activo', version: '1.0.0' });
  });











































































































































































































































  





  // ─── Health check ─────────────────────────────────────────────────────────
  app.get('/health', async (_req, res) => {
    try {
      await prisma.$queryRaw`SELECT 1`;
      res.json({ status: 'ok', db: 'connected', env: env.NODE_ENV });
    } catch {
      res.status(503).json({ status: 'error', db: 'disconnected' });
    }
  });

  // ─── Dev: Get verification code (solo en desarrollo) ─────────────────────
  if (env.NODE_ENV === 'development') {
    app.get('/api/dev/code/:email', async (req, res) => {
      const { email } = req.params;
      const user = await prisma.user.findUnique({ where: { email } });
      if (!user || !user.emailVerifyToken) {
        return res.status(404).json({ error: 'No hay código para este usuario' });
      }
      res.json({
        email,
        code: user.emailVerifyToken,
        expiresAt: user.emailVerifyExpiry,
      });
    });
  }

  // ─── Rutas API ────────────────────────────────────────────────────────────
  app.use('/api/auth', authRouter);
  app.use('/api/users', usersRouter);
  app.use('/api/trips', tripsRouter);
  app.use('/api/requests', requestsRouter);
  app.use('/api/payments', paymentsRouter);
  app.use('/api/ratings', ratingsRouter);
  app.use('/api/reports', reportsRouter);
  app.use('/api/admin', adminRouter);

  // ─── Archivos estáticos (evidencias de reportes) ──────────────────────────
  app.use('/uploads', express.static(path.join(process.cwd(), 'uploads')));

  // ─── 404 ──────────────────────────────────────────────────────────────────
  app.use((_req, res) => {
    res.status(404).json({ error: 'Ruta no encontrada' });
  });

  // ─── Error handler (debe ser el último middleware) ────────────────────────
  app.use(errorHandler);

  return app;
}

import nodemailer, { Transporter } from 'nodemailer';
import { env } from './env';

function createTransporter(): Transporter {
  // En desarrollo sin SMTP configurado → usa ethereal (logs en consola)
  if (!env.SMTP_USER || !env.SMTP_PASS) {
    return nodemailer.createTransport({
      host: 'localhost',
      port: 1025,
      ignoreTLS: true,
    });
  }

  return nodemailer.createTransport({
    host: env.SMTP_HOST,
    port: parseInt(env.SMTP_PORT, 10),
    secure: false,
    auth: {
      user: env.SMTP_USER,
      pass: env.SMTP_PASS,
    },
  });
}

export const mailer = createTransporter();

export async function sendVerificationEmail(email: string, code: string): Promise<void> {
  // En desarrollo sin SMTP → solo log en consola
  if (!env.SMTP_USER || !env.SMTP_PASS) {
    console.log('\n─────────────────────────────────────');
    console.log(`📧 CÓDIGO DE VERIFICACIÓN para ${email}`);
    console.log(`   Código: ${code}`);
    console.log('─────────────────────────────────────\n');
    return;
  }

  await mailer.sendMail({
    from: `"U-Ride UTA" <${env.SMTP_USER}>`,
    to: email,
    subject: 'Verifica tu cuenta en U-Ride',
    html: `
      <div style="font-family: sans-serif; max-width: 480px; margin: 0 auto;">
        <h2 style="color: #1d4ed8;">Verifica tu cuenta en U-Ride</h2>
        <p>Usa el siguiente código para verificar tu correo institucional:</p>
        <div style="background: #f1f5f9; padding: 24px; text-align: center; border-radius: 8px; margin: 24px 0;">
          <span style="font-size: 36px; font-weight: bold; letter-spacing: 8px; color: #1d4ed8;">${code}</span>
        </div>
        <p style="color: #64748b; font-size: 14px;">Este código expira en 15 minutos. Si no solicitaste esto, ignora este correo.</p>
      </div>
    `,
  });
}

