}

import { Request, Response } from 'express';
import { z } from 'zod';
import { prisma } from '../config/database';
import { RequestsService } from '../services/requests.service';
import { emitToTrip } from '../socket/tracking.gateway';

const svc = new RequestsService(prisma);

const createRequestSchema = z.object({
  message: z.string().max(300).optional(),
});

const respondSchema = z.object({
  action: z.enum(['ACCEPT', 'REJECT']),
});

export async function createRequest(req: Request, res: Response) {
  const { message } = createRequestSchema.parse(req.body);
  const request = await svc.create(String(req.params.tripId), req.user!.id, message);
  res.status(201).json({ request });
}

export async function getRequestsByTrip(req: Request, res: Response) {
  const requests = await svc.getByTrip(String(req.params.tripId), req.user!.id);
  res.json({ requests });
}

export async function respondToRequest(req: Request, res: Response) {
  const { action } = respondSchema.parse(req.body);
  const request = await svc.respond(String(req.params.id), req.user!.id, action);

  // Notificar en tiempo real al pasajero si está en la sala del viaje
  emitToTrip((request as any).tripId ?? (request as any).trip?.id, 'request:update', {
    requestId: request.id,
    status: request.status,
  });

  res.json({ request });
}

export async function cancelRequest(req: Request, res: Response) {
  const result = await svc.cancelRequest(String(req.params.id), req.user!.id);
  res.json(result);
}

export async function getMyRequests(req: Request, res: Response) {
  const requests = await svc.getMyRequests(req.user!.id);
  res.json({ requests });
}

import { Request, Response, NextFunction } from 'express';
import { verifyAccessToken } from '../utils/jwt';
import { AppError } from './errorHandler';

export function requireAuth(req: Request, _res: Response, next: NextFunction): void {
  const header = req.headers.authorization;
  if (!header?.startsWith('Bearer ')) {
    throw new AppError(401, 'Token de acceso requerido');
  }

  const token = header.split(' ')[1];
  try {
    const payload = verifyAccessToken(token);
    req.user = { id: payload.userId, email: payload.email, role: payload.role as any };
    next();
  } catch {
    throw new AppError(401, 'Token inválido o expirado');
  }
}

export function requireAdmin(req: Request, _res: Response, next: NextFunction): void {
  if (!req.user) {
    throw new AppError(401, 'No autenticado');
  }
  if (req.user.role !== 'ADMIN') {
    throw new AppError(403, 'Acceso restringido a administradores');
  }
  next();
}

import { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';

export class AppError extends Error {
  constructor(
    public statusCode: number,
    message: string,
  ) {
    super(message);
    this.name = 'AppError';
  }
}

export function errorHandler(
  err: Error,
  _req: Request,
  res: Response,
  _next: NextFunction,
): void {
  if (err instanceof AppError) {
    res.status(err.statusCode).json({ error: err.message });
    return;
  }

  if (err instanceof ZodError) {
    res.status(400).json({
      error: 'Datos inválidos',
      details: err.flatten().fieldErrors,
    });
    return;
  }

  // Error de Prisma: registro duplicado (unique constraint)
  if ((err as any).code === 'P2002') {
    res.status(409).json({ error: 'Ya existe un registro con esos datos' });
    return;
  }

  // Error de Prisma: registro no encontrado
  if ((err as any).code === 'P2025') {
    res.status(404).json({ error: 'Recurso no encontrado' });
    return;
  }

  console.error('Error no controlado:', err);
  res.status(500).json({ error: 'Error interno del servidor' });
}

import { Router } from 'express';
import { z } from 'zod';
import { register, verifyEmail, resendCode, login, refresh, logout, forgotPassword, resetPassword } from '../controllers/auth.controller';
import { requireAuth } from '../middleware/auth.middleware';

const router = Router();

// ─── Schemas de validación ────────────────────────────────────────────────────

const registerSchema = z.object({
  email: z.string().email('Correo inválido'),
  password: z.string().min(8, 'La contraseña debe tener al menos 8 caracteres'),
  fullName: z.string().min(2, 'El nombre debe tener al menos 2 caracteres').max(100),
  career: z.string().max(100).optional(),
});

const verifySchema = z.object({
  email: z.string().email(),
  code: z.string().length(6, 'El código debe tener 6 dígitos'),
});

const loginSchema = z.object({
  email: z.string().email('Correo inválido'),
  password: z.string().min(1, 'Contraseña requerida'),
});

const forgotPasswordSchema = z.object({
  email: z.string().email('Correo inválido'),
});

const resetPasswordSchema = z.object({
  email: z.string().email('Correo inválido'),
  code: z.string().length(6, 'El código debe tener 6 dígitos'),
  newPassword: z.string().min(8, 'La contraseña debe tener al menos 8 caracteres'),
});

// ─── Helper de validación ────────────────────────────────────────────────────

function validate<T>(schema: z.ZodSchema<T>) {
  return (req: any, _res: any, next: any) => {
    schema.parse(req.body);
    next();
  };
}

// ─── Rutas ────────────────────────────────────────────────────────────────────

router.post('/register', validate(registerSchema), register);
router.post('/verify-email', validate(verifySchema), verifyEmail);
router.post('/resend-code', validate(z.object({ email: z.string().email() })), resendCode);
router.post('/login', validate(loginSchema), login);
router.post('/refresh', refresh);
router.post('/logout', logout);
router.post('/forgot-password', validate(forgotPasswordSchema), forgotPassword);
router.post('/reset-password', validate(resetPasswordSchema), resetPassword);

export { router as authRouter };

